13→export function ConfigProvider({ children }: { children: ReactNode }) {
14→  const [maxTotalSizeBytes, setMaxTotalSizeBytes] = useState(DEFAULT_MAX_TOTAL_SIZE_BYTES);
15→
16→  useEffect(() => {
17→    (async () => {
