import { useState, useRef } from 'react';
import { useTranslation } from '../LanguageContext';
import { useAgent } from '../useAgent';
import './ChatInput.css';

export function ChatInput() {
  const { t } = useTranslation();
  const { sendMessage, isStreaming } = useAgent();
  const [text, setText] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSend = () => {
    const trimmed = text.trim();
    if (!trimmed || isStreaming) return;
    sendMessage(trimmed);
    setText('');
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setText(e.target.value);
    const el = e.target;
    el.style.height = 'auto';
    el.style.height = Math.min(el.scrollHeight, 150) + 'px';
  };

  return (
    <div className="chat-input">
      <textarea
        ref={textareaRef}
        className="chat-input__textarea"
        value={text}
        onChange={handleInput}
        onKeyDown={handleKeyDown}
        placeholder={isStreaming ? t('chatPlaceholderWaiting') : t('chatPlaceholder')}
        disabled={isStreaming}
        rows={1}
      />
      <button
        className="chat-input__send"
        onClick={handleSend}
        disabled={isStreaming || !text.trim()}
      >
        {t('send')}
      </button>
    </div>
  );
}

import { useState } from 'react';
import { useTranslation } from '../LanguageContext';
import type { TableInfo } from '../types';
import './Sidebar.css';

interface SidebarProps {
  tables: TableInfo[];
  onTableClick: (tableName: string) => void;
  onTableDelete: (tableName: string) => void;
  collapsed: boolean;
  onToggle: () => void;
}

export function Sidebar({ tables, onTableClick, onTableDelete, collapsed, onToggle }: SidebarProps) {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  const toggle = (name: string) => {
    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
  };

  return (
    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
      <div className="sidebar__header">
        <h3 className="sidebar__title">{t('tablesHeader')}</h3>
        <button
          className="sidebar__collapse-toggle"
          onClick={onToggle}
          aria-label={collapsed ? t('expandSidebar') : t('collapseSidebar')}
        >
          <span className="sidebar__hamburger" />
        </button>
      </div>
      <div className="sidebar__content">
        {tables.length === 0 && (
          <p className="sidebar__empty">{t('noTables')}</p>
        )}
        <ul className="sidebar__list">
          {tables.map((table) => (
            <li key={table.name} className="sidebar__item">
              <div className="sidebar__table-header">
                <button
                  className="sidebar__toggle"
                  onClick={() => toggle(table.name)}
                >
                  {expanded[table.name] ? '\u25BC' : '\u25B6'}
                </button>
                <button
                  className="sidebar__table-name"
                  onClick={() => { onTableClick(table.name); toggle(table.name); }}
                >
                  {table.name}
                </button>
                <span className="sidebar__row-count">
                  {t('rowCount', { count: table.rowCount })}
                </span>
                <button
                  className="sidebar__delete"
                  onClick={(e) => {
                    e.stopPropagation();
                    onTableDelete(table.name);
                  }}
                  title={t('deleteTable', { name: table.name })}
                  aria-label={t('deleteTable', { name: table.name })}
                >
                  🗑
                </button>
              </div>
              {expanded[table.name] && (
                <ul className="sidebar__columns">
                  {table.columns.map((col) => (
                    <li key={col.name} className="sidebar__column">
                      <span className="sidebar__col-name">{col.name}</span>
                      <span className="sidebar__col-type">{col.type}</span>
                    </li>
                  ))}
                </ul>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

import ReactMarkdown from 'react-markdown';
import { useTranslation } from '../LanguageContext';
import type { QueryResult } from '../types';
import './ResultMarkdown.css';

interface ResultMarkdownProps {
  result: QueryResult | null;
}

export function ResultMarkdown({ result }: ResultMarkdownProps) {
  const { t } = useTranslation();
  if (!result) return null;

  const text = result.rows
    .map((row) => Object.values(row).join('\n'))
    .join('\n');

  const markdown = '```\n' + text + '\n```';

  return (
    <div className="result-markdown">
      <div className="result-markdown__summary">
        {t('rowCountInTime', { count: result.rowCount, time: result.executionTimeMs.toFixed(1) })}
      </div>
      <div className="result-markdown__content">
        <ReactMarkdown>{markdown}</ReactMarkdown>
      </div>
    </div>
  );
}

import { useState, useCallback, type KeyboardEvent } from 'react';
import { useTranslation } from '../LanguageContext';
import './QueryEditor.css';

interface QueryEditorProps {
  onExecute: (sql: string) => Promise<void>;
  initialQuery?: string;
}

export function QueryEditor({ onExecute, initialQuery }: QueryEditorProps) {
  const { t } = useTranslation();
  const [sql, setSql] = useState(initialQuery ?? '');
  const [running, setRunning] = useState(false);

  // Update when parent changes initialQuery
  const [prevInitial, setPrevInitial] = useState(initialQuery);
  if (initialQuery !== prevInitial) {
    setPrevInitial(initialQuery);
    if (initialQuery !== undefined) setSql(initialQuery);
  }

  const run = useCallback(async () => {
    const trimmed = sql.trim();
    if (!trimmed || running) return;
    setRunning(true);
    try {
      await onExecute(trimmed);
    } finally {
      setRunning(false);
    }
  }, [sql, running, onExecute]);

  const onKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        run();
      }
    },
    [run]
  );

  return (
    <div className="query-editor">
      <textarea
        className="query-editor__textarea"
        value={sql}
        onChange={(e) => setSql(e.target.value)}
        onKeyDown={onKeyDown}
        placeholder={t('queryPlaceholder')}
        rows={6}
        spellCheck={false}
      />
      <div className="query-editor__actions">
        <button
          className="query-editor__run-btn"
          onClick={run}
          disabled={running || !sql.trim()}
        >
          {running ? t('running') : t('runQuery')}
        </button>
      </div>
    </div>
  );
}

import { useTranslation } from '../LanguageContext';
import type { ToolCallResult } from '../types';
import './InlineQueryResult.css';

const MAX_DISPLAY_ROWS = 20;

function getToolDisplayName(result: ToolCallResult, t: (key: string) => string): string {
  const name = result.toolName || '';
  if (name.includes('execute_sql')) return t('sqlQuery');
  if (name === 'Bash') return t('bash');
  if (name === 'Read') return t('readFile');
  if (name === 'Write') return t('writeFile');
  if (name === 'Edit') return t('editFile');
  if (name.startsWith('mcp__')) {
    const parts = name.split('__');
    return parts[parts.length - 1] || name;
  }
  return name || 'Tool';
}

function getToolInputDisplay(result: ToolCallResult): string | null {
  if (result.sql) return result.sql;
  if (result.command) return result.command;
  if (result.toolInput) {
    const entries = Object.entries(result.toolInput);
    if (entries.length === 0) return null;
    // For single-value inputs, show just the value
    if (entries.length === 1) return String(entries[0][1]);
    return JSON.stringify(result.toolInput, null, 2);
  }
  return null;
}

function isSQL(result: ToolCallResult): boolean {
  return !!result.sql && (result.toolName?.includes('execute_sql') ?? false);
}

export function InlineQueryResult({ result }: { result: ToolCallResult }) {
  const { t } = useTranslation();
  const displayName = getToolDisplayName(result, t);
  const inputDisplay = getToolInputDisplay(result);
  const isSQLTool = isSQL(result);
  const hasStructuredData = result.columns.length > 0;
  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);

  // Determine border color class
  let variantClass = '';
  if (result.error) variantClass = 'inline-query--error';
  else if (result.command) variantClass = 'inline-query--bash';
  else if (!isSQLTool && !result.sql) variantClass = 'inline-query--generic';

  return (
    <div className={`inline-query ${variantClass}`}>
      {/* Tool label */}
      <div className={`inline-query__label ${isSQLTool ? 'inline-query__label--sql' : result.command ? 'inline-query__label--bash' : 'inline-query__label--generic'}`}>
        {displayName}
      </div>

      {/* Tool input */}
      {inputDisplay && (
        <div className="inline-query__sql">
          <code>{inputDisplay}</code>
        </div>
      )}

      {/* Error display */}
      {result.error && (
        <div className="inline-query__error">{result.error}</div>
      )}

      {/* SQL structured results */}
      {!result.error && isSQLTool && hasStructuredData && (
        <>
          <div className="inline-query__table-wrapper">
            <table className="inline-query__table">
              <thead>
                <tr>
                  {result.columns.map((col) => (
                    <th key={col}>{col}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {displayRows.map((row, i) => (
                  <tr key={i}>
                    {result.columns.map((col) => (
                      <td key={col}>{String(row[col] ?? '')}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="inline-query__meta">
            {t('rowCount', { count: result.rowCount })}
            {result.rowCount > MAX_DISPLAY_ROWS && ` ${t('showingCount', { count: MAX_DISPLAY_ROWS })}`}
          </div>
        </>
      )}

      {/* Text output for non-SQL tools */}
      {!result.error && result.output && (
        <div className="inline-query__output">
          <pre>{result.output}</pre>
        </div>
      )}

      {/* Raw content fallback */}
      {!result.error && !hasStructuredData && !result.output && result.rawContent && (
        <div className="inline-query__raw">
          <pre>{result.rawContent}</pre>
        </div>
      )}

      {/* Pending state */}
      {!result.error && !hasStructuredData && !result.output && !result.rawContent && inputDisplay && (
        <div className="inline-query__meta">{t('executing')}</div>
      )}
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { useTranslation } from '../LanguageContext';
import { useAgent } from '../useAgent';
import { ChatInput } from './ChatInput';
import { MessageBubble } from './MessageBubble';
import { FileUpload } from './FileUpload';
import type { LangfuseStatus, TableInfo } from '../types';
import './AgentPanel.css';

interface AgentPanelProps {
  langfuseStatus: LangfuseStatus;
  tables: TableInfo[];
  onUpload: (files: File[]) => Promise<void>;
  onLoadSample: () => Promise<void>;
}

export function AgentPanel({ langfuseStatus, tables, onUpload, onLoadSample }: AgentPanelProps) {
  const { t } = useTranslation();
  const { messages, clearMessages } = useAgent();
  const bottomRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  return (
    <div className="agent-panel">
      <div className="agent-panel__header">
        <span className="agent-panel__title">{t('agentMode')}</span>
        <div className="agent-panel__actions">
          <button
            className={`agent-panel__langfuse ${!langfuseStatus.enabled ? 'agent-panel__langfuse--disabled' : ''}`}
            disabled={!langfuseStatus.enabled}
            title={langfuseStatus.enabled ? t('openLangfuse') : t('langfuseNotConfigured')}
            onClick={() => {
              if (langfuseStatus.dashboardUrl) {
                window.open(langfuseStatus.dashboardUrl, '_blank', 'noopener,noreferrer');
              }
            }}
          >
            <img src="/langfuse-color.svg" alt="Langfuse" className="agent-panel__langfuse-icon" />
            {t('langfuseTraces')}
          </button>
          {messages.length > 0 && (
            <button className="agent-panel__clear" onClick={clearMessages}>
              {t('clear')}
            </button>
          )}
        </div>
      </div>
      <div className="agent-panel__messages">
        {messages.length === 0 && (
          <div className="agent-panel__empty">
            {tables.length === 0 ? (
              <FileUpload onUpload={onUpload} onLoadSample={onLoadSample} />
            ) : (
              t('agentEmptyState')
            )}
          </div>
        )}
        {messages.map((msg, index) => (
          <MessageBubble key={msg.id} message={msg} messageIndex={index} />
        ))}
        <div ref={bottomRef} />
      </div>
      <ChatInput />
    </div>
  );
}

import { useState, useMemo, useRef, useEffect } from 'react';
import { useTranslation } from '../LanguageContext';
import type { QueryResult } from '../types';
import './ResultsTable.css';

interface ResultsTableProps {
  result: QueryResult | null;
}

const DISPLAY_CAP = 1000;

interface SortConfig {
  column: string | null;
  direction: 'asc' | 'desc';
}

export function ResultsTable({ result }: ResultsTableProps) {
  const { t } = useTranslation();
  const [sortConfig, setSortConfig] = useState<SortConfig>({ column: null, direction: 'asc' });
  const [columnFilters, setColumnFilters] = useState<Record<string, string>>({});
  const [globalFilter, setGlobalFilter] = useState('');
  const prevResult = useRef<QueryResult | null>(null);

  useEffect(() => {
    if (result !== prevResult.current) {
      prevResult.current = result;
      setSortConfig({ column: null, direction: 'asc' });
      setColumnFilters({});
      setGlobalFilter('');
    }
  }, [result]);

  const filteredRows = useMemo(() => {
    if (!result) return [];
    let rows = result.rows;

    if (globalFilter) {
      const term = globalFilter.toLowerCase();
      rows = rows.filter((row) =>
        result.columns.some((col) => formatCell(row[col]).toLowerCase().includes(term))
      );
    }

    const activeFilters = Object.entries(columnFilters).filter(([, v]) => v);
    if (activeFilters.length > 0) {
      rows = rows.filter((row) =>
        activeFilters.every(([col, term]) =>
          formatCell(row[col]).toLowerCase().includes(term.toLowerCase())
        )
      );
    }

    return rows;
  }, [result, globalFilter, columnFilters]);

  const sortedRows = useMemo(() => {
    if (!sortConfig.column) return filteredRows;
    const col = sortConfig.column;
    const dir = sortConfig.direction === 'asc' ? 1 : -1;

    return [...filteredRows].sort((a, b) => {
      const aVal = a[col];
      const bVal = b[col];

      if (aVal === null || aVal === undefined) return 1;
      if (bVal === null || bVal === undefined) return -1;

      const aNum = Number(aVal);
      const bNum = Number(bVal);
      if (!isNaN(aNum) && !isNaN(bNum)) return (aNum - bNum) * dir;

      return String(aVal).localeCompare(String(bVal)) * dir;
    });
  }, [filteredRows, sortConfig]);

  if (!result) return null;

  const isFiltered = globalFilter || Object.values(columnFilters).some(Boolean);
  const displayRows = sortedRows.slice(0, DISPLAY_CAP);
  const truncated = sortedRows.length > DISPLAY_CAP;

  function handleSort(col: string) {
    setSortConfig((prev) => {
      if (prev.column !== col) return { column: col, direction: 'asc' };
      if (prev.direction === 'asc') return { column: col, direction: 'desc' };
      return { column: null, direction: 'asc' };
    });
  }

  function handleColumnFilter(col: string, value: string) {
    setColumnFilters((prev) => ({ ...prev, [col]: value }));
  }

  function getSortIcon(col: string) {
    if (sortConfig.column !== col) return ' ↕';
    return sortConfig.direction === 'asc' ? ' ↑' : ' ↓';
  }

  return (
    <div className="results-table">
      <div className="results-table__toolbar">
        <input
          className="results-table__global-search"
          type="text"
          placeholder={t('searchColumns')}
          value={globalFilter}
          onChange={(e) => setGlobalFilter(e.target.value)}
        />
      </div>
      <div className="results-table__summary">
        {isFiltered
          ? t('rowsFilteredInTime', { count: sortedRows.length, total: result.rowCount, time: result.executionTimeMs.toFixed(1) })
          : t('rowCountInTime', { count: result.rowCount, time: result.executionTimeMs.toFixed(1) })}
        {truncated && ` ${t('showingFirst', { count: DISPLAY_CAP })}`}
      </div>
      {result.columns.length > 0 && (
        <div className="results-table__scroll">
          <table className="results-table__table">
            <thead>
              <tr>
                {result.columns.map((col) => (
                  <th key={col}>
                    <button
                      className="results-table__col-header"
                      onClick={() => handleSort(col)}
                    >
                      {col}
                      <span
                        className={`results-table__sort-icon${sortConfig.column === col ? ' results-table__sort-icon--active' : ''}`}
                      >
                        {getSortIcon(col)}
                      </span>
                    </button>
                    <input
                      className="results-table__col-filter"
                      type="text"
                      placeholder={t('filterPlaceholder')}
                      value={columnFilters[col] || ''}
                      onChange={(e) => handleColumnFilter(col, e.target.value)}
                    />
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {displayRows.map((row, i) => (
                <tr key={i}>
                  {result.columns.map((col) => (
                    <td key={col}>{formatCell(row[col])}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function formatCell(value: unknown): string {
  if (value === null || value === undefined) return 'NULL';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

import { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { useTranslation } from '../LanguageContext';
import type { ChatMessage, ContentSegment } from '../types';
import { useAgent } from '../useAgent';
import { InlineQueryResult } from './InlineQueryResult';
import './MessageBubble.css';

function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
  // Use streaming remainder if available
  if (streamingRemainder?.trim()) {
    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
    const last = lines[lines.length - 1] || '';
    return last.length > 100 ? last.slice(0, 100) + '...' : last;
  }
  // Otherwise use last thinking segment's last line
  for (let i = segments.length - 1; i >= 0; i--) {
    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
      const last = lines[lines.length - 1] || '';
      return last.length > 100 ? last.slice(0, 100) + '...' : last;
    }
  }
  return t('thinking');
}

function ThinkingBlock({ segments, streamingRemainder, isActivelyStreaming }: {
  segments: ContentSegment[];
  streamingRemainder?: string;
  isActivelyStreaming: boolean;
}) {
  const { t } = useTranslation();
  // All non-answer segments go inside the thinking block
  const thinkingSegments = segments.filter((s) => s.type !== 'answer');
  const hasContent = thinkingSegments.some(
    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult)
  ) || streamingRemainder?.trim();

  if (!hasContent) return null;

  const summary = getLastThinkingLine(segments, streamingRemainder, t);

  return (
    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isActivelyStreaming || undefined}>
      <summary className="message-bubble__collapsible-summary">
        <span className="message-bubble__segment-label">{t('thinkingLabel')}</span>
        <span className="message-bubble__collapsible-preview">{summary}</span>
      </summary>
      <div className="message-bubble__thinking-body">
        {thinkingSegments.map((seg, i) => {
          if (seg.type === 'thinking' && seg.text?.trim()) {
            return (
              <div key={i} className="message-bubble__segment-content">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
              </div>
            );
          }
          if (seg.type === 'tool' && seg.toolResult) {
            return (
              <div key={i} className="message-bubble__tool-segment">
                <InlineQueryResult result={seg.toolResult} />
              </div>
            );
          }
          return null;
        })}
        {streamingRemainder?.trim() && (
          <div className="message-bubble__segment-content">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
          </div>
        )}
      </div>
    </details>
  );
}

export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
  const { t } = useTranslation();
  const { isStreaming, editMessage, deleteMessage } = useAgent();
  const [isEditing, setIsEditing] = useState(false);
  const [editText, setEditText] = useState(message.content);
  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const isUser = message.role === 'user';
  const hasSegments = !isUser && message.segments && message.segments.length > 0;

  useEffect(() => {
    if (isEditing && textareaRef.current) {
      textareaRef.current.focus();
      textareaRef.current.selectionStart = textareaRef.current.value.length;
    }
  }, [isEditing]);

  const handleEdit = () => {
    setEditText(message.content);
    setIsEditing(true);
    setIsConfirmingDelete(false);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
    setEditText(message.content);
  };

  const handleSaveEdit = () => {
    const trimmed = editText.trim();
    if (!trimmed || trimmed === message.content) {
      handleCancelEdit();
      return;
    }
    setIsEditing(false);
    editMessage(messageIndex, trimmed);
  };

  const handleDeleteConfirm = () => {
    setIsConfirmingDelete(false);
    deleteMessage(messageIndex);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      handleCancelEdit();
    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      handleSaveEdit();
    }
  };

  let streamingRemainder: string | undefined;
  if (hasSegments && message.isStreaming && message.content) {
    const segmentedText = message.segments!
      .filter((s) => s.type !== 'tool')
      .map((s) => s.text || '')
      .join('');
    const remaining = message.content.slice(segmentedText.length);
    if (remaining.trim()) {
      streamingRemainder = remaining;
    }
  }

  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
  const isInAnswerPhase = message.currentPhase === 'answer';
  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;

  const answerSegments = hasSegments
    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
    : [];

  return (
    <div className={`message-bubble message-bubble--${message.role}`}>
      <div className="message-bubble__header">
        {isUser ? t('you') : t('assistant')}
        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
          <span className="message-bubble__actions">
            <button
              className="message-bubble__action-btn"
              onClick={handleEdit}
              title={t('editMessage')}
            >
              &#9998;
            </button>
            <button
              className="message-bubble__action-btn message-bubble__action-btn--delete"
              onClick={() => setIsConfirmingDelete(true)}
              title={t('deleteMessage')}
            >
              &#128465;
            </button>
          </span>
        )}
      </div>

      {isUser && isConfirmingDelete && (
        <div className="message-bubble__confirm-delete">
          <span>{t('deleteConfirm')}</span>
          <div className="message-bubble__confirm-actions">
            <button
              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
              onClick={handleDeleteConfirm}
            >
              {t('delete')}
            </button>
            <button
              className="message-bubble__confirm-btn"
              onClick={() => setIsConfirmingDelete(false)}
            >
              {t('cancel')}
            </button>
          </div>
        </div>
      )}

      {isUser && isEditing ? (
        <div className="message-bubble__edit-mode">
          <textarea
            ref={textareaRef}
            className="message-bubble__edit-textarea"
            value={editText}
            onChange={(e) => setEditText(e.target.value)}
            onKeyDown={handleKeyDown}
            rows={3}
          />
          <div className="message-bubble__edit-actions">
            <button
              className="message-bubble__edit-btn message-bubble__edit-btn--save"
              onClick={handleSaveEdit}
            >
              {t('saveResend')}
            </button>
            <button
              className="message-bubble__edit-btn"
              onClick={handleCancelEdit}
            >
              {t('cancel')}
            </button>
          </div>
        </div>
      ) : hasSegments ? (
        <div className="message-bubble__segments">
          <ThinkingBlock
            segments={message.segments!}
            streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
            isActivelyStreaming={isThinkingPhase}
          />
          {answerSegments.map((seg, i) => (
            <div key={i} className="message-bubble__segment message-bubble__segment--answer">
              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
              <div className="message-bubble__segment-content">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
              </div>
            </div>
          ))}
          {isInAnswerPhase && !hasAnswer && streamingRemainder?.trim() && (
            <div className="message-bubble__segment message-bubble__segment--answer">
              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
              <div className="message-bubble__segment-content">
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
              </div>
            </div>
          )}
          {message.isStreaming && !message.content && (
            <span className="message-bubble__typing">{t('thinking')}</span>
          )}
        </div>
      ) : (
        <>
          <div className="message-bubble__content">
            {message.content ? (
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
            ) : message.isStreaming ? (
              <span className="message-bubble__typing">{t('thinking')}</span>
            ) : null}
          </div>
          {message.toolCalls && message.toolCalls.length > 0 && (
            <div className="message-bubble__tools">
              {message.toolCalls.map((tc) => (
                <InlineQueryResult key={tc.toolCallId} result={tc} />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

