export function ConfigProvider({ children }: { children: ReactNode }) {
  const [maxTotalSizeBytes, setMaxTotalSizeBytes] = useState(DEFAULT_MAX_TOTAL_SIZE_BYTES);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch('/api/config');
